"""V2 quantities, US purchasing, delegated labor and owner-PDF phase budgeting."""
from pathlib import Path
import json,csv,math,html
from owner_plan import ROOT,RUN

def main():
    quantities=json.loads((RUN/'materials/quantities.json').read_text(encoding='utf-8'));q={r['item']:r['net_quantity'] for r in quantities['items']};project=json.loads((RUN/'project/project-plan.json').read_text(encoding='utf-8'));rates=json.loads((ROOT/'materials/us-rate-scenario-2026-11-02.json').read_text(encoding='utf-8'));sources=rates['sources'];rows=[]
    pcurl='https://www.greenhousemegastore.com/products/16mm-polycarbonate-clear';glurl='https://store.angelesmillwork.com/products/glulam-beam-5-1-8--x-18--lf-7058.html'
    def add(name,qty,unit,lo,hi,basis,source='',status='Authored allowance',net=None,waste=None):
        url=sources[source]['url'] if source in sources else source
        rows.append(dict(item=name,net_quantity=net,purchase_quantity=qty,unit=unit,waste_percent=waste,rate_low_usd=lo,rate_high_usd=hi,low_usd=round(qty*lo,2),high_usd=round(qty*hi,2),status=status,source_url=url,basis=basis))
    for part in ['Concrete footings','Concrete slab','Retaining concrete core']:add(part,math.ceil(q[part]*1.05*4)/4,'cy',180,280,'Native volume +5%, quarter-yard rounding; mix/steel and remote delivery unquoted','concrete',net=q[part],waste=5)
    add('Rebar, chairs, ties, dowels and structural anchors',1,'lot',7000,15000,'No bar schedule exists; material cash allowance only. Engineer specifies pounds and placement.')
    add('Subslab aggregate',math.ceil(q['Subslab aggregate']*1.1),'cy',50,90,'10% loose-volume reserve; grading and freight not measured','aggregate',net=q['Subslab aggregate'],waste=10)
    add('2 in XPS subslab, 4 x 8 ft',math.ceil(q['Subslab insulation']*1.1/32),'board',55.82,70,'25 psi benchmark; project bearing/thermal/termite requirements TBD','xps2','Advertised benchmark + upper reserve',q['Subslab insulation'],10)
    add('4 in XPS walls, 4 x 8 ft',math.ceil(q['Wall rigid insulation']*1.1/32),'board',111.63,140,'4 in board catalog benchmark; not 3 in board price','xps3','Advertised catalog benchmark + upper reserve',q['Wall rigid insulation'],10)
    add('15 mil underslab barrier, 14 x 140 ft',math.ceil(q['Slab vapor barrier']*1.15/1960),'roll',1266.75,1520,'15% laps/cuts, full rolls; membrane modeled thickness exaggerated for visibility','vapor','Advertised benchmark + upper reserve',q['Slab vapor barrier'],15)
    add('Foundation waterproofing, nominal 200 sf',math.ceil(q['Wall waterproofing']*1.15/200),'roll',235.49,307,'15% waste/laps; all exterior faces retained in concept','wallwater','Advertised benchmark + upper reserve',q['Wall waterproofing'],15)
    add('Drainage/protection, 4 x 50 ft',math.ceil(q['Wall drainage/protection']*1.1/200),'roll',292.96,381,'10% cutting/lap reserve; approved compatible system required','drainmat','Advertised benchmark + upper reserve',q['Wall drainage/protection'],10)
    add('Membrane primers, seals, boots and terminations',1,'lot',2500,5500,'Professional compatible waterproofing detail required; not optional','wallwater')
    add('Engineer-approved footing drain, 10 ft sticks',math.ceil(q['Footing drain reservation']*1.1/10),'stick',25,55,'Final deep-burial pipe class required. Supplier thin-wall link is price context, not approval for the proposed burial.','pipe',net=q['Footing drain reservation'],waste=10)
    add('Drain stone, geotextile, cleanouts and separate outlets',1,'lot',3500,8000,'Drain trench, gravity outlet and runoff lengths require survey; no drainage through planters to footing system.','aggregate')
    add('Glulam 5-1/8 x 18 in section reservation, 28 ft cut-stock',14,'beam',28*35,28*65,'14 modeled full-span beams; section/grade/cantilever, 28 ft length, fabrication, bearings, warranty and delivery require stamped design and TWO supplier quotes.',glurl,net=q['Glulam beam reservation'])
    add('2x8 roof purlins, 8 ft stock equivalents',math.ceil(q['Roof purlin 2x8']*1.15/8),'board-equivalent',12,20,'Dressed 1.5 x 7.25 in; 24 in grid from US profile; buy/cut/splice and grade need engineer. No order-ready cut list.','https://www.homedepot.com/b/Lumber-Composites-Dimensional-Lumber-Framing-Lumber/N-5yc1vZc55w',net=q['Roof purlin 2x8'],waste=15)
    add('2x6 glazing frame, 8 ft stock equivalents',math.ceil(q['Glazing frame 2x6']*1.15/8),'board-equivalent',8.62,12,'Dressed 1.5 x 5.5 in; quote glazing-curb frame separately from panel profiles.','2x6',net=q['Glazing frame 2x6'],waste=15)
    add('2x4 partition stock, 10 ft equivalents',math.ceil(q['Partition timber 2x4']*1.15/10),'board-equivalent',4.98,6.5,'Dressed 1.5 x 3.5 in and 16 in grid; variable-height stud cuts/header allowances require final coordination.','2x4',net=q['Partition timber 2x4'],waste=15)
    add('Roof bearings, connectors, rims and miscellaneous blocking',1,'lot',5000,11000,'Includes engineered beam-bearing connectors and unmodeled blocking/header details; no second complete glulam charge.','joist')
    add('Engineer-specified exposed wood protection / finish materials',1,'lot',1500,3500,'Required by owner brief: select compatible coating, substrate prep, garden-humidity exposure and PC/gasket separation details. No coating product or treatment compatibility is assumed.')
    add('Opaque roof 23/32 in plywood, 4 x 8 ft',math.ceil(q['Opaque roof deck']*1.1/32),'sheet',46.75,60,'Only opaque half; 10% cutting waste. Supplier search-price benchmark, full page retrieval blocked.','plywood','Supplier benchmark; confirm',q['Opaque roof deck'],10)
    add('Opaque roof insulation, TWO 3 in 4 x 8 ft layers',2*math.ceil(q['Opaque roof insulation']*1.1/32),'board',55,90,'Roof-approved new polyiso; two layers counted, not applied to PC half. Thermal assembly unresolved.','roofiso',net=2*q['Opaque roof insulation'],waste=10)
    add('Opaque roof membrane/coverboard/flashings/gutters package',1,'lot',6000,11000,'Only opaque half, plus its perimeter details; roof junction to PC priced separately.','epdm')
    add('16 mm (~5/8 in) multiwall PC, 4 x 28 ft QUOTE RESERVATION',14,'panel-equivalent',112*6,112*10,'13 modeled columns plus spare. 28 ft length is NOT verified stock; final length/system or revised rectangle must be designed around approved panels. $/sf rate is authored, not a 28 ft supplier quote.',pcurl,net=q['Polycarbonate 5/8 in nominal reservation'])
    add('Glazing bars, thermal-movement joints, gaskets, tapes and opaque/PC transition',1,'lot',6500,14000,'Engineer/manufacturer-specific hybrid roof assembly, no assumed multiwall sheet butt/end lap. Main transition about 27 ft; all panel joints also included.',pcurl)
    add('Retractable solar-control allowance (unmodeled)',1,'lot',3500,8500,'Budget-only retractable shading allowance, fully open in review. No fixed shade slats or measured shade lumber. Thermal, mounting and wind design unresolved.',pcurl)
    add('High-level roof vent assemblies / controls',4,'each',600,1400,'Four geometric reservations only; actual aperture/actuation/flashings and capacity need ventilation and glazing design.',pcurl)
    add('Glazed garden humidity screen and sliding access',1,'lot',6500,12500,'Approximately 209 sf screen reservation plus 8 ft sliding opening. Separates humidity; final thermal/fire/condensation details TBD.',net=q['Glazed garden separation reservation'])
    add('Partition 1/2 in drywall, 4 x 8 ft',math.ceil(q['Partition lining']*1.1/32),'sheet',19.74,25,'10% waste; wet-area backer separately in interior finish materials.','drywall','Advertised benchmark + upper reserve',q['Partition lining'],10)
    add('Interior mineral finish on retained wall faces',math.ceil(q['Exterior wall inside finish']*1.1),'sf',1.25,2.5,'Materials only; bonding and moisture compatibility need specification.',net=q['Exterior wall inside finish'],waste=10)
    add('Five door units and hardware',5,'each',400,1000,'Three exterior / two interior reservations; price range blended, verify products, rough openings and escape hardware.')
    add('Three exterior windows',1,'lot',5000,10500,'Living, kitchen and garden unit reservations; supplier/fire/thermal safety design required.')
    add('Waterproof planters and independent garden irrigation/drain materials',1,'lot',5000,12000,'Two planters about 168 sf of bed footprint, not the whole 800 sf garden. Include liners, growing medium and controlled overflow; no footing-drain discharge.',net=q['Waterproofed planter reservation'])
    add('One kitchen / bathroom / laundry plumbing and fixture materials',1,'lot',6500,12000,'One bathroom rather than old two-bath ranch; mechanical water heater equipment separate.')
    add('Approved well/septic short house-connection materials reserve',1,'lot',2500,6500,'Written approvals, actual distances and connection design missing. No new well drilling or new septic field purchase included.')
    add('House wiring, panel, alarms, lights and existing-power interface',1,'lot',7000,13000,'Existing off-grid generation/storage already acquired; no PV/battery/generator purchase or utility extension.')
    add('ERV, garden latent-load/dehumidification provision, heat pump and water heater',1,'lot',18000,32000,'Equipment/material reserve; ERV alone is not a sizing result or guarantee of humidity control. Mechanical designer to calculate plant/water/solar/occupant loads.')
    add('Cabinets, counters, appliances, flooring, backers, paint and trim materials',1,'lot',20000,35000,'One combined living/sleeping zone, one kitchen/bath service zone and garden. No three-bedroom finish package.')
    labor_specs=[('3','Site layout and excavation',160,300,2,65,95),('4','Footings / rebar / pours',200,360,4,50,80),('4','Retaining-wall forms / steel / pours / strip',520,900,5,50,85),('4','Subslab services and concrete floor',190,320,3,50,80),('5','Wall waterproofing and drainage',250,420,3,50,80),('5','Engineer-released backfill / immediate grading',120,240,2,65,95),('6','Glulam erection and wood roof frame',400,680,4,55,90),('6','Opaque and PC roof / gaskets / flashings',300,520,3,65,105),('6','Shading and roof vent installation',120,220,2,55,90),('8','Partitions and humidity screen',180,320,3,50,85),('7','Water/septic connections and house plumbing',120,220,2,75,115),('7','House electrical and existing-power interface',100,180,2,75,115),('7','ERV / HVAC / garden humidity installation',140,240,2,80,120),('8','Wall finishes, floors and painting',380,650,3,45,75),('8','Kitchen / bath / laundry fit-out',180,320,3,55,90),('8','Garden / waterproof planters / irrigation',120,240,2,50,85),('9','Final tests / cleanup / punch list',100,180,2,65,100)]
    labor=[dict(phase_id=phase,trade=trade,person_hours_low=a,person_hours_high=b,crew=crew,billable_usd_per_worker_hour_low=lo,billable_usd_per_worker_hour_high=hi,labor_low_usd=a*lo,labor_high_usd=b*hi,active_crew_weeks_low=round(a/(crew*40),2),active_crew_weeks_high=round(b/(crew*40),2),basis='Authored effort/rates, not quote. Operator labor included; machine hire separate. Work must fit engineer sequencing and private hold releases; no owner DIY labor.') for phase,trade,a,b,crew,lo,hi in labor_specs]
    total=lambda rs,side:round(sum(r[side+'_usd'] for r in rs),2)
    mat=[total(rows,side) for side in ['low','high']];lab=[round(sum(r['labor_'+side+'_usd'] for r in labor),2) for side in ['low','high']]
    equipment=[dict(item='Excavation / compaction machinery, trucking and mobilization',low_usd=16000,high_usd=34000,basis='Machines/fuel/trucking only; operator labor in trade rows; no measured excavation volume'),dict(item='Concrete forms hire, pumping, roof lifting and temporary restraint reserve',low_usd=14000,high_usd=30000,basis='Temporary restraint must be engineered, not improvised. Equipment/consumables only; labor separately counted.')]
    eq=[total(equipment,side) for side in ['low','high']];direct=[round(mat[i]+lab[i]+eq[i],2) for i in range(2)]
    mandatory=[dict(item='Architect and coordinated drawings',low_usd=15000,high_usd=35000,basis='Required by owner brief; unquoted professional allowance'),dict(item='Structural / roof / envelope engineering and stamps',low_usd=20000,high_usd=45000,basis='Required, includes hybrid joints, glulam and retaining design; scope quote needed'),dict(item='Soils / geotechnical study',low_usd=4000,high_usd=8000,basis='Required before engineered foundations/retaining design'),dict(item='Independent hold-point inspections and retests',low_usd=8700,high_usd=22000,basis='Nine hold points with $800-$2,000/report scenario plus $1,500-$4,000 retest reserve; no inspector quote'),dict(item='Delegated PM / owner representative',low_usd=32400,high_usd=108000,basis='72 weeks x 6-12 hours/week x $75-$125/hour authored range. Owner approves only; no DIY or free PM execution assumed.')]
    mandatory_total=[total(mandatory,side) for side in ['low','high']]
    extra=[dict(item='Land / existing off-grid equipment acquisition',low_usd=0,high_usd=0,basis='Already acquired per user'),dict(item='Material freight / remote delivery',low_usd=round(mat[0]*.08,2),high_usd=round(mat[1]*.12,2),basis='8%-12% authored reserve; actual quotes needed. Equipment trucking separately listed excludes supply freight.'),dict(item='Sales / use tax',low_usd=round(mat[0]*.08,2),high_usd=round(mat[1]*.10,2),basis='Unverified 8%-10% reserve, not a tax determination'),dict(item='Illustrative contingency - NOT APPROVED',low_usd=round(direct[0]*.2,2),high_usd=round(direct[1]*.2,2),basis='20% example only. Owner brief requires PM proposal after bids and owner approval; no approved percentage exists.')]
    estimate=dict(revision='Owner PDF V2',date='2026-11-02',source_sha256=quantities['source_sha256'],native_sha256=quantities['native_sha256'],brief_sha256=quantities['brief_sha256'],material_low_usd=mat[0],material_high_usd=mat[1],labor_low_usd=lab[0],labor_high_usd=lab[1],equipment_low_usd=eq[0],equipment_high_usd=eq[1],construction_low_usd=direct[0],construction_high_usd=direct[1],mandatory_program_low_usd=mandatory_total[0],mandatory_program_high_usd=mandatory_total[1],material_rows=rows,labor_rows=labor,equipment_rows=equipment,mandatory_professional_rows=mandatory,separate_rows=extra,overall_project_weeks=[1,72],construction_phase_envelope_weeks=[22,72],closeout='After week 72, duration TBD',actuals_status='No quotes, actual invoices, supplier deliveries or approvals on file',supplier_sources=sources)
    (RUN/'materials/estimate.json').write_text(json.dumps(estimate,indent=2),encoding='utf-8')
    def csvout(name,data):
        with (RUN/'materials'/name).open('w',newline='',encoding='utf-8-sig') as f:w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)
    for name,data in [('us-purchasing-and-costs.csv',rows),('trade-labor.csv',labor),('equipment.csv',equipment),('mandatory-professionals.csv',mandatory),('separate-budget-items.csv',extra)]:csvout(name,data)
    cash=[]
    for r in project['phases']:cash.append(dict(phase=r['id'],description=r['phase'],project_weeks=f'{r["start_week"]}-{r["end_week"]}' if r['start_week'] else 'after 72',release=r['gate'],budget_from_awarded_bids_usd='',committed_usd='',paid_usd='',forecast_usd='',evidence='',status='NOT AUTHORIZED / budget to be built from bids'))
    if (RUN/'project/phase-cash-tracker.csv').exists():
        with (RUN/'project/phase-cash-tracker.csv').open(newline='',encoding='utf-8-sig') as f:previous={r['phase']:r for r in csv.DictReader(f)}
        for row in cash:
            for field in ['budget_from_awarded_bids_usd','committed_usd','paid_usd','forecast_usd','evidence','status']:
                if row['phase'] in previous and previous[row['phase']].get(field,'')!='':row[field]=previous[row['phase']][field]
    with (RUN/'project/phase-cash-tracker.csv').open('w',newline='',encoding='utf-8-sig') as f:w=csv.DictWriter(f,fieldnames=list(cash[0]));w.writeheader();w.writerows(cash)
    mo=lambda x:f'${x:,.0f}';esc=html.escape
    def table(headers,data):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in r)+'</tr>' for r in data)+'</tbody></table></div>'
    material_table=table(['US material / stock','Purchase quantity','USD unit low-high','USD extended low-high','Evidence / source'],[[esc(r['item']),f'{r["purchase_quantity"]:g} {esc(r["unit"])}',mo(r['rate_low_usd'])+'–'+mo(r['rate_high_usd']),mo(r['low_usd'])+'–'+mo(r['high_usd']),esc(r['status'])+'<br>'+esc(r['basis'])+(f'<br><a href="{esc(r["source_url"])}">Supplier / product reference</a>' if r['source_url'] else '')] for r in rows])
    labor_table=table(['Trade / PDF phase','Person-hours','Crew','USD / person-hour','Labor cost','Active crew weeks'],[[esc(r['trade'])+' / '+r['phase_id'],f'{r["person_hours_low"]}–{r["person_hours_high"]}',str(r['crew']),f'{r["billable_usd_per_worker_hour_low"]}–{r["billable_usd_per_worker_hour_high"]}',mo(r['labor_low_usd'])+'–'+mo(r['labor_high_usd']),f'{r["active_crew_weeks_low"]}–{r["active_crew_weeks_high"]}'] for r in labor])
    simple=lambda data:table(['Scope','Low USD','High USD','Basis'],[[esc(r['item']),mo(r['low_usd']),mo(r['high_usd']),esc(r['basis'])] for r in data])
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Owner brief V2 · Construction and program budget</title><link rel="stylesheet" href="../../../assets/site.css?v=owner-v2"></head><body><main><nav><a href="../../../index.html">← Current design</a><a href="us-purchasing-and-costs.csv">US purchasing CSV</a><a href="trade-labor.csv">Trade hours CSV</a><a href="../project/index.html">Project controls</a></nav><header><p class="eyebrow">OWNER PDF REVISION · PROVISIONAL QUANTITIES · USD</p><h1>Glulam, glazing, garden.</h1><p class="lede">Updated for 2,500 sf gross, one combined living/sleeping zone, central service zone and garden. No three-bedroom or full-opaque-roof budget carried forward.</p></header><div class="metrics"><article><span>Construction materials</span><strong>{mo(mat[0])}–{mo(mat[1])}</strong></article><article><span>Delegated trade labor</span><strong>{mo(lab[0])}–{mo(lab[1])}</strong></article><article><span>Equipment / restraint / formwork</span><strong>{mo(eq[0])}–{mo(eq[1])}</strong></article></div><p class="notice">Direct construction scenario: {mo(direct[0])}–{mo(direct[1])}. Mandatory design/private inspection/PM, freight, tax and contingency are separate below. No actual local bids or approved spending exist. Land and existing off-grid power remain acquired.</p><section><h2>Mandatory professional and management scope</h2><p>The owner brief makes private engineering and inspections essential, and assigns execution to a PM/trades. No owner DIY or free project-management labor is assumed.</p>{simple(mandatory)}<p>Additional professional/program allowance: <b>{mo(mandatory_total[0])}–{mo(mandatory_total[1])}</b>. No professional has been hired or quoted.</p></section><section><h2>Schedule basis</h2><p>Use the owner's <b>weeks 1–72 overall envelope, plus close-out after week 72</b>. Site/construction phases are roughly project weeks 22–72; design, approvals and long-lead procurement precede them. This replaces the old 21–37 week hired-crew estimate.</p><p>Active crew weeks below are effort/(crew × 40 hours), not a delivery promise. Different trades overlap, hold-point releases can stop work, and final supplier dates/engineered sequence may lengthen the envelope. In particular, full backfill needs engineered restraint; it cannot be released merely because waterproofing was inspected.</p></section><section><h2>Model-derived US purchasing</h2><p>Net geometry, waste and full-pack assumptions remain separate in the CSV. Glulam section/grade and 28 ft lengths, PC 28 ft panel equivalents, connection sizes and thermal/vent systems are unapproved reservations, not order specifications. Existing retailer prices remain benchmarks; all newly introduced engineered-system rates are authored allowances.</p>{material_table}</section><section><h2>Delegated trade labor</h2><p>Per-worker billed rates and hours are authored planning inputs. Costs = person-hours × rate; crew count affects duration, never multiplies the bill twice. Equipment and professional/inspection fees are separately counted.</p>{labor_table}</section><section><h2>Equipment and temporary works</h2>{simple(equipment)}</section><section><h2>Separately held budget items</h2>{simple(extra)}<p>New wells, new septic fields, major utility runs, blasting/dewatering and soil-covered roof are not priced. Approved water/septic connections are provisional short-run allowances; the actual records and distances are missing. The phase cash tracker leaves committed/paid/actual values blank until there is real evidence.</p><a href="../project/phase-cash-tracker.csv">Phase cash tracker</a></section><footer>Draft only · Not for construction · Raw owner PDF retained locally · <a href="../project/brief-reconciliation.md">Requirements and source reconciliation</a></footer></main></body></html>'''
    (RUN/'materials/costs.html').write_text(doc,encoding='utf-8')
    md=['# Owner-PDF construction and program estimate','',f'Materials {mo(mat[0])}–{mo(mat[1])}; trade labor {mo(lab[0])}–{mo(lab[1])}; equipment {mo(eq[0])}–{mo(eq[1])}. Direct construction {mo(direct[0])}–{mo(direct[1])}.','',f'Mandatory architect/engineering/geotechnical/private inspections/delegated PM are separately reserved at {mo(mandatory_total[0])}–{mo(mandatory_total[1])}. Land and off-grid equipment acquisition remain zero. No spending or contingency percentage is approved.','', '## Timing','', 'Owner plan weeks 1–72 overall; construction envelope approximately weeks 22–72, then closeout with duration TBD. Quotes, supply dates and gate releases govern. No old 21–37 week promise is retained. Backfill before the roof requires specifically engineered temporary restraint or deferral until permanent restraint is accepted.','', '## Sourcing and limits','', 'See [HTML report](costs.html), [purchasing CSV](us-purchasing-and-costs.csv), [labor CSV](trade-labor.csv), [model quantities](bill-of-materials.csv) and [project controls](../project/index.html).','', '5-1/8 x 18 in glulam and 16 mm (~5/8 in) PC are model reservations; 28 ft supply lengths and grades are not verified stock. Do not order from the model. Obtain two written PC/glulam quotes and at least three bids per trade after coordinated specifications. Roof/frame/shade/vent joints need the structural/envelope/manufacturer design. Thermal and humidity performance is uncalculated.','', 'All construction pricing is an estimate, not a supplier quote, installed bid or actual invoice. New engineered-system rates are authored allowances. Retained supplier price references are in the repository rate scenario. Mandatory private engineering/inspections are not removed to reduce cost. Actuals/commitments are blank in the phase cash tracker.','',f'Source SHA256 `{quantities["source_sha256"]}`',f'Native SHA256 `{quantities["native_sha256"]}`',f'Owner brief SHA256 `{quantities["brief_sha256"]}`','']
    (RUN/'materials/cost-breakdown.md').write_text('\n'.join(md),encoding='utf-8')
    print('OWNER COSTS',json.dumps({k:estimate[k] for k in ['material_low_usd','material_high_usd','labor_low_usd','labor_high_usd','construction_low_usd','construction_high_usd']}))
if __name__=='__main__':main()
